import java.util.*;

public class Main {
    public static void main(String[] args) {
        Calendar calendar = new Calendar();

        // Two existing events: 9:00-10:00 (540-600) and 10:30-11:30 (630-690), minutes since midnight.
        System.out.println("Add 540-600: " + calendar.addEvent(540, 600));
        System.out.println("Add 630-690: " + calendar.addEvent(630, 690));

        // A conflicting booking: 9:30-10:15 (570-615) overlaps the first event.
        System.out.println("Add 570-615 (should conflict): " + calendar.addEvent(570, 615));

        // A booking that fits exactly in the gap: 10:00-10:30 (600-630).
        System.out.println("Add 600-630 (should succeed): " + calendar.addEvent(600, 630));

        System.out.println("Final calendar events, in order: " + calendar.allEventsSorted());

        // Recurrence: a weekly series starting day 0, every 7 days, 4 occurrences.
        RecurrenceRule rule = new RecurrenceRule(0, 7, 4);
        RecurrenceExpander expander = new RecurrenceExpander();

        Map<Integer, Long> overrides = new HashMap<>();
        overrides.put(2, 16L); // the 3rd occurrence (index 2, originally day 14) is moved to day 16
        Set<Integer> cancelled = new HashSet<>();
        cancelled.add(1); // the 2nd occurrence (index 1, day 7) is cancelled

        List<Long> occurrences = expander.expand(rule, overrides, cancelled);
        System.out.println("Expanded occurrences (base 0,7,14,21 with index1 cancelled, index2 moved to 16): " + occurrences);
    }
}

// One concrete, non-recurring event on a calendar.
class Event {
    long start;
    long end;

    Event(long start, long end) {
        this.start = start;
        this.end = end;
    }
}

// A single calendar's non-overlapping events, sorted by start time, supporting
// an efficient conflict check against only the immediately adjacent neighbors.
class Calendar {
    private final TreeMap<Long, Event> eventsByStart = new TreeMap<>();

    // Returns true if the given interval overlaps an existing event.
    boolean hasConflict(long start, long end) {
        Map.Entry<Long, Event> before = eventsByStart.floorEntry(start); // the event starting at or before this new start
        if (before != null && before.getValue().end > start) {
            return true; // the preceding event ends after this new event starts: overlap
        }
        Map.Entry<Long, Event> after = eventsByStart.ceilingEntry(start); // the event starting at or after this new start
        if (after != null && after.getKey() < end) {
            return true; // the following event starts before this new event ends: overlap
        }
        return false;
    }

    // Adds the event only if it does not conflict; returns whether it was added.
    boolean addEvent(long start, long end) {
        if (hasConflict(start, end)) {
            return false;
        }
        eventsByStart.put(start, new Event(start, end));
        return true;
    }

    List<String> allEventsSorted() {
        List<String> result = new ArrayList<>();
        for (Event event : eventsByStart.values()) {
            result.add(event.start + "-" + event.end);
        }
        return result;
    }
}

// A compact, fixed-interval recurrence rule: a start day, an interval in days
// between occurrences, and a total occurrence count.
class RecurrenceRule {
    long startDay;
    long intervalDays;
    int occurrenceCount;

    RecurrenceRule(long startDay, long intervalDays, int occurrenceCount) {
        this.startDay = startDay;
        this.intervalDays = intervalDays;
        this.occurrenceCount = occurrenceCount;
    }
}

// Expands a recurrence rule into concrete occurrence days, applying any
// per-occurrence overrides (moved dates) or cancellations on top of the base schedule.
class RecurrenceExpander {
    List<Long> expand(RecurrenceRule rule, Map<Integer, Long> overrides, Set<Integer> cancelled) {
        List<Long> result = new ArrayList<>();
        for (int i = 0; i < rule.occurrenceCount; i++) {
            if (cancelled.contains(i)) {
                continue; // this occurrence is cancelled entirely; skip it
            }
            long day = overrides.containsKey(i) ? overrides.get(i) : (rule.startDay + i * rule.intervalDays);
            result.add(day);
        }
        return result;
    }
}

