#include <iostream>
#include <map>
#include <set>
#include <vector>
#include <string>
using namespace std;

// One concrete, non-recurring event on a calendar.
struct Event {
    long start;
    long end;
};

// A single calendar's non-overlapping events, sorted by start time,
// supporting an efficient conflict check against only the immediately
// adjacent neighbors, since this calendar's own events never already overlap.
class Calendar {
public:
    bool hasConflict(long start, long end) {
        auto before = eventsByStart.upper_bound(start);
        if (before != eventsByStart.begin()) {
            --before; // the event starting at or before this new start
            if (before->second.end > start) {
                return true; // the preceding event ends after this new event starts: overlap
            }
        }
        auto after = eventsByStart.lower_bound(start); // the event starting at or after this new start
        if (after != eventsByStart.end() && after->first < end) {
            return true; // the following event starts before this new event ends: overlap
        }
        return false;
    }

    bool addEvent(long start, long end) {
        if (hasConflict(start, end)) {
            return false;
        }
        eventsByStart[start] = Event{start, end};
        return true;
    }

    vector<string> allEventsSorted() {
        vector<string> result;
        for (const auto& entry : eventsByStart) {
            result.push_back(to_string(entry.second.start) + "-" + to_string(entry.second.end));
        }
        return result;
    }

private:
    map<long, Event> eventsByStart; // sorted by start time
};

// A compact, fixed-interval recurrence rule: a start day, an interval in days
// between occurrences, and a total occurrence count.
struct RecurrenceRule {
    long startDay;
    long intervalDays;
    int occurrenceCount;
};

// Expands a recurrence rule into concrete occurrence days, applying any
// per-occurrence overrides (moved dates) or cancellations on top of the base schedule.
class RecurrenceExpander {
public:
    vector<long> expand(const RecurrenceRule& rule, const map<int, long>& overrides, const set<int>& cancelled) {
        vector<long> result;
        for (int i = 0; i < rule.occurrenceCount; i++) {
            if (cancelled.count(i)) {
                continue; // this occurrence is cancelled entirely; skip it
            }
            auto it = overrides.find(i);
            long day = (it != overrides.end()) ? it->second : (rule.startDay + (long)i * rule.intervalDays);
            result.push_back(day);
        }
        return result;
    }
};

int main() {
    Calendar calendar;

    // Two existing events: 9:00-10:00 (540-600) and 10:30-11:30 (630-690), minutes since midnight.
    cout << "Add 540-600: " << (calendar.addEvent(540, 600) ? "true" : "false") << endl;
    cout << "Add 630-690: " << (calendar.addEvent(630, 690) ? "true" : "false") << endl;

    // A conflicting booking: 9:30-10:15 (570-615) overlaps the first event.
    cout << "Add 570-615 (should conflict): " << (calendar.addEvent(570, 615) ? "true" : "false") << endl;

    // A booking that fits exactly in the gap: 10:00-10:30 (600-630).
    cout << "Add 600-630 (should succeed): " << (calendar.addEvent(600, 630) ? "true" : "false") << endl;

    cout << "Final calendar events, in order: ";
    for (const auto& e : calendar.allEventsSorted()) cout << e << " ";
    cout << endl;

    // Recurrence: a weekly series starting day 0, every 7 days, 4 occurrences.
    RecurrenceRule rule{0, 7, 4};
    RecurrenceExpander expander;

    map<int, long> overrides = { {2, 16} }; // the 3rd occurrence (index 2, originally day 14) is moved to day 16
    set<int> cancelled = { 1 }; // the 2nd occurrence (index 1, day 7) is cancelled

    vector<long> occurrences = expander.expand(rule, overrides, cancelled);
    cout << "Expanded occurrences (base 0,7,14,21 with index1 cancelled, index2 moved to 16): ";
    for (long d : occurrences) cout << d << " ";
    cout << endl;

    return 0;
}

